// One item per city, carrying all three URLs it needs. Everything comes from
// columns `cities` already has - no station discovery hop.
const cfg = $('Config').first().json;
const cities = $('Load cities').all().map(i => i.json).flat();
const cap = Number(cfg.max_cities_per_run || 0) || 0;
const obsHours = Number(cfg.observation_hours || 30);
const obsLimit = Number(cfg.observation_limit || 60);
// No fractional seconds. api.weather.gov documents these as ISO8601 and
// accepts `2026-09-04T07:05:20Z`; the milliseconds toISOString() adds are
// one more thing that can be rejected for no benefit.
const sinceIso = new Date(Date.now() - obsHours * 3600_000)
  .toISOString().replace(/\.\d{3}Z$/, 'Z');

const out = [];
// SCOPE. run_scope() decides which cities this run covers and should_run()
// carries the answer, so this costs no extra node and no extra request. A
// workflow that ignores the field behaves exactly as it always did; absent,
// "all", or a selection matching nothing all mean every active city, because
// a scope that silently reduces a run to zero is indistinguishable from a
// broken job.
const _scope = (($('Check schedule').first().json ?? {}).scope) ?? {};
const _only = Array.isArray(_scope.cities) && _scope.cities.length
  ? new Set(_scope.cities) : null;

for (const c of cities) {
  if (!c || !c.city_key) continue;
  if (_only && !_only.has(c.city_key)) continue;
  // Skip cities a previous run already proved are not US stations.
  if (c.nws_supported === false) continue;
  if (!c.icao || c.latitude == null || c.longitude == null) continue;

  const lat = Number(c.latitude).toFixed(4);
  const lon = Number(c.longitude).toFixed(4);

  // PostgREST returns an EMBEDDED resource as an array (or an object), never a
  // bare string: prior_alert arrives as [{nws_alert: 'Heat Advisory'}]. Left in
  // that shape, `event !== prior_alert` below is always true and every single
  // run re-raises the same standing alert - which is exactly the email spam the
  // change-detection exists to prevent. Flatten it here.
  const pa = c.prior_alert;
  const prior = Array.isArray(pa) ? ((pa[0] && pa[0].nws_alert) ?? null)
              : (pa && typeof pa === 'object' ? (pa.nws_alert ?? null)
              : (pa ?? null));

  out.push({ json: {
    city_key: c.city_key,
    icao: c.icao,
    unit: c.unit || 'C',
    prior_alert: prior,
    // The SERIES, not just the latest reading. This is what the weather.gov
    // hourly tab shows and what the market settles against - and a single
    // reading cannot give a daily maximum, which is the number being traded.
    // A short window keeps it cheap; the archive backfill is a separate job.
    obs_url:    `https://api.weather.gov/stations/${encodeURIComponent(c.icao)}/observations` +
                `?start=${encodeURIComponent(sinceIso)}&limit=${obsLimit}`,
    alerts_url: `https://api.weather.gov/alerts/active?point=${lat},${lon}`,
    point_url:  `https://api.weather.gov/points/${lat},${lon}`,
  }});
  if (cap && out.length >= cap) break;
}
if (out.length === 0) {
  throw new Error('No cities with an icao and coordinates. NWS needs both. ' +
                  'Check cities.icao / latitude / longitude are populated.');
}
return out;

// Turn three NWS responses per city into rows for three tables.
//
// api.weather.gov returns every measurement as a QuantitativeValue:
//   {"value": 22.2, "unitCode": "wmoUnit:degC", "qualityControl": "V"}
// The unitCode is authoritative - never assume Celsius.
const requests = $('Build requests').all().map(i => i.json);
// THE BUG THAT MADE ALL 37 CITIES "FAIL".
// n8n's HTTP node autodetects the response format from Content-Type, and its
// test is `contentType.includes('application/json')`. api.weather.gov answers
// `application/geo+json` (and `application/problem+json` on an error), neither
// of which contains that substring - so every response was decoded as TEXT and
// arrived as `{ data: "{\"properties\":..." }`. No `properties`, no `status`,
// no `title`: not a 404, not an error, just nothing to read. Hence "0 are not
// US, 37 failed" with no detail to report, in both P1.2 and P1.3, forever.
// The Fetch nodes now set responseFormat=json explicitly. This re-parses a
// string body regardless, so the workflow also works on an n8n build that
// names that option differently.
function asJson(v) {
  if (v == null) return {};
  if (typeof v === 'string') {
    const s = v.trim();
    if (s.startsWith('{') || s.startsWith('[')) { try { return JSON.parse(s); } catch (e) {} }
    return { error: 'unparseable body: ' + s.slice(0, 200) };
  }
  if (typeof v !== 'object') return {};
  if (typeof v.data === 'string') {
    const s = v.data.trim();
    if (s.startsWith('{') || s.startsWith('[')) { try { return JSON.parse(s); } catch (e) {} }
  }
  if (typeof v.body === 'string') {
    const s = v.body.trim();
    if (s.startsWith('{') || s.startsWith('[')) { try { return JSON.parse(s); } catch (e) {} }
  }
  return v;
}

const obsRes   = $('Fetch observation').all().map(i => asJson(i.json));
const alertRes = $('Fetch alerts').all().map(i => asJson(i.json));
const pointRes = $('Fetch point').all().map(i => asJson(i.json));

const cfg = $('Config').first().json;
const alertEvents = (cfg.alert_events || '').split(',').map(s => s.trim()).filter(Boolean);

const now = new Date().toISOString();

// QuantitativeValue -> Celsius, honouring unitCode.
function degC(qv) {
  if (!qv || qv.value === null || qv.value === undefined) return null;
  const v = Number(qv.value);
  if (!Number.isFinite(v)) return null;
  const unit = String(qv.unitCode || '');
  if (unit.includes('degF')) return Number(((v - 32) * 5 / 9).toFixed(4));
  if (unit.includes('K'))    return Number((v - 273.15).toFixed(4));
  return Number(v.toFixed(4));   // degC
}
function num(qv) {
  if (!qv || qv.value === null || qv.value === undefined) return null;
  const v = Number(qv.value);
  return Number.isFinite(v) ? v : null;
}
// weather_observations was filled by IEM METAR, so its columns carry METAR's
// units: wind_speed is KNOTS (sknt) and precip is INCHES (p01i).
// api.weather.gov answers in km/h and mm. Writing those through unconverted
// would put 37 in a knots column for a 20kt wind - wrong, but not
// wrong-LOOKING, which is the kind of error nobody finds.
//
// An unrecognised unitCode returns null rather than the raw number: a value
// whose unit is unknown is not a measurement, and these columns are nullable.
function knots(qv) {
  const v = num(qv);
  if (v === null) return null;
  const u = String(qv.unitCode || '');
  if (u.includes('km_h')) return Number((v / 1.852).toFixed(3));
  if (u.includes('m_s'))  return Number((v * 1.9438445).toFixed(3));
  if (u.includes('mi_h')) return Number((v * 0.8689762).toFixed(3));
  if (u.includes('knot') || u.includes('kt')) return Number(v.toFixed(3));
  return null;
}
function inches(qv) {
  const v = num(qv);
  if (v === null) return null;
  const u = String(qv.unitCode || '');
  if (u.includes('mm')) return Number((v / 25.4).toFixed(4));
  if (u.includes('cm')) return Number((v / 2.54).toFixed(4));
  if (u.includes('m') && !u.includes('mm') && !u.includes('cm'))
    return Number((v * 39.3701).toFixed(4));
  if (u.includes('in')) return Number(v.toFixed(4));
  return null;
}
// METAR sky cover -> oktas, matching scripts/ingest_observations.sky_oktas so
// the two feeds store cloud_cover the same way.
const OKTAS = { SKC:0, CLR:0, NSC:0, NCD:0, FEW:2, SCT:4, BKN:6, OVC:8, VV:8 };
function oktas(layers) {
  if (!Array.isArray(layers) || !layers.length) return null;
  let worst = null;
  for (const l of layers) {
    const o = OKTAS[String(l && l.amount || '').toUpperCase()];
    if (o !== undefined && (worst === null || o > worst)) worst = o;
  }
  return worst;
}

// WHAT THE FAILURE ACTUALLY WAS.
// This used to report only a count - "37 failed" - which says nothing about
// whether weather.gov refused the User-Agent, rejected the query, timed out or
// was never reached. Every one of those needs a different fix and they were
// indistinguishable. Keep the first failing response verbatim.
let firstFailure = null;
function describe(req, o) {
  if (!o) return { city: req.city_key, url: req.obs_url, problem: 'no response object at all' };
  if (o.error) {
    return { city: req.city_key, url: req.obs_url, problem: 'request error',
             error: String(o.error).slice(0, 300) };
  }
  return {
    city: req.city_key, url: req.obs_url,
    problem: 'response had no observations',
    http_status: o.status ?? null,
    title: o.title ?? null,
    detail: typeof o.detail === 'string' ? o.detail.slice(0, 200) : null,
    keys: Object.keys(o).slice(0, 12),
    body: JSON.stringify(o).slice(0, 400),
  };
}

const observations = [], liveRows = [], events = [];
let ok = 0, notUS = 0, failed = 0;
const support = [];   // city_key -> nws_supported, written back to cities

for (let i = 0; i < requests.length; i++) {
  const req = requests[i];
  const o = obsRes[i], a = alertRes[i], p = pointRes[i];

  // A 404 means this ICAO is not an api.weather.gov station - almost always a
  // non-US city. Record that so the next run skips it instead of asking again.
  // A series answers as a FeatureCollection - `features`, no `properties`.
  // The original guard predates that shape and treated every series response
  // as a failed fetch, silently dropping the whole point of the change.
  const missing = !o || o.error || (!o.properties && !o.features && !o.status);
  const is404 = o && (o.status === 404 || String(o.title || '').includes('Not Found'));
  if (is404 || missing) {
    if (is404) { notUS++; support.push({ city_key: req.city_key, nws_supported: false, nws_station_id: null, nws_grid_wfo: null, nws_grid_x: null, nws_grid_y: null, nws_checked_at: now }); }
    else { failed++; if (!firstFailure) firstFailure = describe(req, o); }
    continue;
  }

  // A series response is a FeatureCollection; `latest` was a single Feature.
  // Handle both, so a station that only answers the old shape still works.
  const obsFeats = Array.isArray(o.features) ? o.features
                 : (o.properties ? [{ properties: o.properties }] : []);
  const readings = obsFeats
    .map(f => f && f.properties)
    .filter(pr => pr && pr.timestamp && degC(pr.temperature) !== null)
    .sort((a, b) => String(a.timestamp).localeCompare(String(b.timestamp)));

  // THE PATH A 403 OR 400 ACTUALLY TAKES. Those responses carry a `status`
  // field, so the `missing` test above passes them through and the 404 test
  // does not match either - they arrive here, with no readings. Instrumenting
  // only the first failure branch left exactly the two cases most likely to be
  // the real cause reporting "No detail captured".
  if (readings.length === 0) {
    failed++;
    if (!firstFailure) firstFailure = describe(req, o);
    continue;
  }

  // The newest reading drives live_weather; every reading is archived.
  const props = readings[readings.length - 1];
  const tempC = degC(props.temperature);
  ok++;

  const pp = (p && p.properties) || {};
  const astro = pp.astronomicalData || {};

  support.push({
    city_key: req.city_key,
    nws_supported: true,
    nws_station_id: req.icao,
    nws_grid_wfo: pp.gridId ?? null,
    nws_grid_x: pp.gridX ?? null,
    nws_grid_y: pp.gridY ?? null,
    nws_checked_at: now,
  });

  // ---- one row per READING, alongside the IEM ones for the same instants --
  // The unique key is (city_key, valid_at, source), so a whole series upserts
  // safely and re-running costs nothing. This is what makes a daily MAXIMUM
  // computable from NWS at all - one reading never could.
  for (const pr of readings) {
    const t = degC(pr.temperature);
    observations.push({
      city_key: req.city_key,
      // cities.icao, not the id NWS echoes back: IEM rows store the ICAO, and a
      // different form here would split one station across two values.
      station: req.icao,
      valid_at: pr.timestamp,
      temp_c: t,
      temp_f: t === null ? null : Number((t * 9 / 5 + 32).toFixed(2)),
      dewpoint_c: degC(pr.dewpoint),
      humidity: num(pr.relativeHumidity),
      wind_speed: knots(pr.windSpeed),      // knots, like IEM's sknt
      wind_dir_deg: num(pr.windDirection),  // degrees either way
      precip: inches(pr.precipitationLastHour),  // inches, like IEM's p01i
      cloud_cover: oktas(pr.cloudLayers),
      source: 'NWS',
    });
  }

  // ---- alerts -------------------------------------------------------------
  const feats = (a && Array.isArray(a.features)) ? a.features : [];
  let headline = null, severity = null, event = null, alertId = null;
  for (const f of feats) {
    const ap = f.properties || {};
    // Only heat-relevant events, unless the operator listed none at all.
    if (alertEvents.length && !alertEvents.includes(ap.event)) continue;
    headline = ap.headline || ap.event || null;
    severity = ap.severity || null;
    event = ap.event || null;
    alertId = ap.id || null;
    break;                                  // the most urgent one wins
  }

  // Only raise an event when the alert CHANGED, so re-running does not spam.
  if (event && event !== req.prior_alert) {
    events.push({
      city_key: req.city_key,
      kind: 'nws_alert',
      // NWS severity -> AD4's four levels
      severity: ({ Extreme: 'critical', Severe: 'high', Moderate: 'medium' })[severity] || 'low',
      temp_c: tempC,
      detail: { source: 'api.weather.gov', event, headline, nws_severity: severity,
                nws_id: alertId, station: req.icao },
    });
  }

  // ---- live_weather -------------------------------------------------------
  liveRows.push({
    city_key: req.city_key,
    updated_at: now,
    observed_at: props.timestamp,
    temp_c: tempC,
    temp_f: tempC === null ? null : Number((tempC * 9 / 5 + 32).toFixed(2)),
    humidity: num(props.relativeHumidity),
    wind_speed_kt: knots(props.windSpeed),
    wind_dir_deg: num(props.windDirection),
    // station-REPORTED daily maximum, not one we computed from samples
    max_temp_24h_c: degC(props.maxTemperatureLast24Hours),
    solar_transit_at: astro.transit ?? null,
    sunrise_at: astro.sunrise ?? null,
    sunset_at: astro.sunset ?? null,
    nws_alert: event,
    nws_alert_severity: severity,
    obs_source: 'NWS',
  });
}

return [{ json: {
  observations, liveRows, events, support,
  n_obs: observations.length, n_events: events.length,
  ok, not_us: notUS, failed, requested: requests.length,
  first_failure: firstFailure,
} }];

const p = $('Build rows').first().json;
if (p.n_obs === 0) {
  const f = p.first_failure;
  // A count is not a diagnosis, and a diagnosis on line three is not a
  // diagnosis either: n8n's banner shows the first line, and the first line is
  // what gets pasted into a bug report. "Parsed 0 observations from 37 cities"
  // was reported three times with the reason sitting unread underneath it.
  let why = 'No observations parsed and no failing response was captured - which should be impossible; report this.';
  if (f) {
    if (f.problem === 'no response object at all') {
      why = `The "Fetch observation" node produced an EMPTY item for this city - no body at all. That is n8n dropping the response, not weather.gov: check that "Fetch observation" has Never Error on and is not being rate-limited (lower Batch Size in its options).`;
    } else if (f.problem === 'request error') {
      why = `The request never completed: ${f.error}. api.weather.gov was not reached - check n8n's outbound network, or raise the timeout on Fetch observation.`;
    } else if (f.http_status === 403) {
      why = `weather.gov answered 403 Forbidden. It REQUIRES a User-Agent identifying your app and refuses generic ones. Open the Config node and make sure user_agent is filled in (something like "ArbDesk4 (your-email@example.com)").`;
    } else if (f.http_status === 400) {
      why = `weather.gov answered 400 Bad Request: ${f.detail || f.title || ''}. The query was malformed rather than the station being wrong.`;
    } else if (f.http_status) {
      why = `weather.gov answered ${f.http_status} ${f.title || ''}. ${f.detail || ''}`;
    } else if ((f.keys || []).length === 1 && f.keys[0] === 'data') {
      // The failure this workflow actually had: a body decoded as text.
      why = `weather.gov answered, but n8n decoded the body as TEXT instead of JSON, so there was nothing to read. Open the "Fetch observation" node -> Options -> Response -> Response Format and set it to JSON, and do the same on "Fetch point" and "Fetch alerts". (api.weather.gov sends Content-Type: application/geo+json, which n8n's autodetect does not recognise as JSON.)`;
    } else {
      why = `The response had none of the fields expected. Keys: ${(f.keys || []).join(', ')}. Body: ${f.body}`;
    }
  }
  throw new Error(
    why +
    ` [${p.not_us}/${p.requested} not US stations, ${p.failed}/${p.requested} failed, nothing written]` +
    (f ? `\n\nFirst failing city: ${f.city}\nURL: ${f.url}` : ''));
}
return [{ json: p }];

const AD4_WRITE_NODES = ["Write observations", "Write live_weather", "Save NWS ids", "Raise alerts"];
// AD4-WRITE-GUARD
// DID THE DATABASE ACTUALLY TAKE IT?
//
// Every write node in this workflow carries onError=continueRegularOutput so
// that one bad row cannot kill a run. The cost of that is a REFUSED write
// walks straight past it and arrives here looking healthy - which is how a
// workflow reports "ok, 0 rows" for days while the data quietly stops moving.
//
// With neverError on, a refusal arrives as the PostgREST error body instead of
// an exception, so it can be read and named. That is what this does.
function ad4WriteError(node) {
  // WHAT ACTUALLY WENT WRONG, NOT THE FIRST THING THAT LOOKED LIKE AN ERROR.
  //
  // This used to return the first item carrying a `code` or `message` and stop.
  // A Supabase gateway timeout arrives as {"data":"upstream request timeout"} -
  // no code, no message - so it was skipped ENTIRELY, and on a run where 90 of
  // 102 writes timed out the guard reported the single PGRST102 it found
  // instead. The message named a key mismatch; the cause was an overloaded
  // database. That cost an evening.
  //
  // So: classify every item, count the kinds, and report the one that
  // dominates, with the counts, so the next person reads the truth first.
  let items;
  try { items = $(node).all(); } catch (e) { return null; }
  const kinds = {};
  let first = null, n = 0;
  for (const it of items || []) {
    const b = it && it.json;
    if (!b || typeof b !== 'object') continue;
    n++;
    let e = null;
    if (typeof b.data === 'string' && /timeout|timed out|502|503|504/i.test(b.data)) {
      e = { node, code: 'TIMEOUT', message: b.data.slice(0, 300) };
    } else if (b.error && !b.code) {
      e = { node, code: null, message: String(b.error).slice(0, 300) };
    } else if (b.code || b.message) {
      e = { node, code: b.code ?? null, message: b.message ?? '',
            details: b.details ?? null, hint: b.hint ?? null };
    }
    if (!e) continue;
    const key = String(e.code ?? e.message).slice(0, 60);
    kinds[key] = (kinds[key] || 0) + 1;
    if (!first || kinds[key] > kinds[String(first.code ?? first.message).slice(0, 60)]) first = e;
  }
  if (!first) return null;
  const key = String(first.code ?? first.message).slice(0, 60);
  first.count = kinds[key];
  first.of = n;
  first.kinds = kinds;
  return first;
}

for (const node of AD4_WRITE_NODES) {
  const e = ad4WriteError(node);
  if (!e) continue;
  // 42501 is the one worth naming, because the cause is never in the code.
  if (String(e.code) === 'TIMEOUT') {
    throw new Error(
      `Supabase did not answer ${e.count} of ${e.of} write(s) at "${e.node}": ${e.message}. ` +
      `That is the DATABASE being too busy to reply, not a bad row - retrying the same run ` +
      `harder will not help. Check whether several workflows are running at once, and look ` +
      `at the Supabase project's load. Whatever did not time out was written; the rest was not.`);
  }
  if (String(e.code) === '42501' || /permission denied/i.test(e.message)) {
    throw new Error(
      `Supabase REFUSED the write at "${e.node}": ${e.message} (${e.code}). The key was ` +
      `already checked at "Run now?" and claims to be the service key, so this is the ` +
      `DATABASE side: service_role has no INSERT on that table. Run sql/ad4_38_grants.sql ` +
      `in the Supabase SQL editor - it grants the write path back, then prints one row per ` +
      `ingest table saying whether the service key can write it. Nothing was written.`);
  }
  if (String(e.code) === '42P01') {
    throw new Error(
      `Supabase has no such table for "${e.node}": ${e.message}. The sql/ files that create ` +
      `it have not been run - sql/ad4_98_ui_health.sql names which file owns which table. ` +
      `Nothing was written.`);
  }
  throw new Error(
    `Supabase refused the write at "${e.node}": ${e.message}` +
    (e.code ? ` (${e.code})` : '') + (e.details ? ` - ${e.details}` : '') +
    (e.hint ? ` Hint: ${e.hint}` : '') + ' Nothing was written.');
}

const p = $('Build rows').first().json;
const rows = p.n_obs || 0;
const summary =
  `AD4 P1.2: ${rows} NWS observations from ${p.requested} cities` +
  (p.not_us ? `, ${p.not_us} not US stations` : '') +
  (p.failed ? `, ${p.failed} failed` : '') +
  (p.n_events ? `. ${p.n_events} weather alert(s) raised` : '. no new alerts') + '.';
const status = rows > 0 ? (p.n_events ? 'attention' : 'ok') : 'attention';
const detail = { requested: p.requested, not_us: p.not_us, failed: p.failed,
                 alerts: p.n_events };
return [{ json: {
  summary, status, rows,
  log: { p_job: 'P1.2_nws_monitor', p_status: status, p_rows: rows,
         p_detail: { ...detail, summary, trigger: $execution.mode, execution_id: $execution.id } },
} }];

// AD4-KEY-CHECK
// THE KEY IS NOT IN THIS FILE ANY MORE, AND THAT IS THE POINT.
//
// Every Supabase node in this workflow authenticates with an n8n SUPABASE
// CREDENTIAL rather than a key pasted into the Config node. That is one place
// to set it instead of twelve, it is encrypted at rest in n8n, and exporting
// this workflow can no longer leak it - the old shape had the service key
// sitting in plain text inside a JSON file that gets emailed around.
//
// SET IT UP ONCE, BEFORE IMPORTING ANYTHING:
//   n8n -> Credentials -> New -> Supabase API
//     Name         AD4 Supabase        <- this name exactly
//     Host         https://<your-project-ref>.supabase.co
//     Service Role the SERVICE ROLE key (Project Settings -> API keys)
//
// The name matters because every Supabase node in every AD4 workflow is
// already bound to a credential called AD4 Supabase. Create it first and
// n8n links all of them on import - nothing to pick node by node. Import
// first and the nodes come in unbound, and you pick the credential on each
// one by hand; it works, it is just ~57 dropdowns instead of zero.
//
// The credential sends `apikey` and `Authorization: Bearer` itself, which is
// exactly what these nodes used to set by hand.
//
// WHAT STILL CHECKS THE KEY. This node can no longer read it - a credential
// is not visible to an expression, by design. Two things downstream do:
//
//   the schedule gate, immediately below. sql/ad4_38 revokes should_run from
//   anon, so a credential holding the publishable key is refused HERE, two
//   nodes in, before a single row is fetched.
//
//   the write guard in the Summary node, which names any refusal the
//   database gives and refuses to report success on a run that wrote nothing.
//
// supabase_url stays in Config because an expression has to build the request
// URL and cannot read the credential's host. It is not a secret.
{
  const cfg = $('Config').first().json ?? {};
  const url = String(cfg.supabase_url ?? '').trim();
  if (!url) {
    throw new Error(
      'Config -> supabase_url is empty. Set it to exactly ' +
      'https://<your-project-ref>.supabase.co - no trailing slash and no /rest/v1, ' +
      'which every node below appends itself. The KEY does not go here: it belongs in ' +
      'the n8n Supabase credential (Credentials -> New -> Supabase API), which is ' +
      'where the nodes now read it from.');
  }
  if (!/^https:\/\//.test(url) || /\/rest\b/.test(url) || /\/$/.test(url)) {
    throw new Error(
      `Config -> supabase_url is "${url}", which is not the shape every node below ` +
      'expects: https://<your-project-ref>.supabase.co, no trailing slash, no /rest/v1. ' +
      'Nothing was fetched and nothing was written.');
  }
}

// Ask the database whether this run should do anything.
//
// n8n cannot be told from outside not to FIRE a schedule trigger, so the saving
// is here: returning no items stops every node below, and the execution ends
// having done two trivial requests instead of the whole job.
//
// settings.workflow_schedules owns the answer (sql/ad4_20_schedules.sql) and
// the Workflows page edits it. A manual or webhook run always proceeds - a Run
// button that obeyed the cadence would be a Run button that does nothing.
const d = $('Check schedule').first().json ?? {};
const decision = Array.isArray(d) ? d[0] : d;

// A PERMISSION ERROR IS NOT AN UNAVAILABLE GATE. 42501 here means the key
// cannot even call should_run, and a key that cannot do that cannot write
// either - so stop, rather than failing open into a run that writes nothing.
//
// THIS NODE CANNOT CHECK THE KEY ITSELF ANY MORE - it is in the credential,
// which an expression cannot read. So a refusal here is one of two things and
// both stop the run: the credential holds the anon/publishable key rather than
// the service role key, or service_role has not been granted what it needs.
// Either way every write below would be refused the same way, so there is
// nothing to gain by going on. ad4_38's output tells you which it was.
//
// ad4_38 revokes should_run from anon for this reason: it was granted so the
// Workflows page could preview a cadence, that page reads v_execution_budget
// instead, and the grant only let a bad key through the gate.
if (decision && (String(decision.code) === '42501' ||
                 /permission denied/i.test(String(decision.message || '')))) {
  throw new Error(
    `Supabase refused should_run: ${decision.message} (${decision.code}). Every write below ` +
    `would be refused the same way, so nothing was fetched and nothing was written. Two ` +
    `things cause this and the workflow cannot tell them apart, because the key now lives ` +
    `in the n8n credential where an expression cannot read it. (1) THE KEY: open n8n -> ` +
    `Credentials -> the Supabase account these nodes use and check Service Role Secret ` +
    `holds the SERVICE ROLE key (Supabase -> Project Settings -> API -> service_role, or a ` +
    `key beginning sb_secret_) - an anon key gets exactly this error, because anon is ` +
    `granted SELECT and nothing else. NEVER put the service key anywhere starting ` +
    `NEXT_PUBLIC_. (2) THE DATABASE: service_role has not been granted what it needs. Run ` +
    `sql/ad4_38_grants.sql in the Supabase SQL editor - it grants the write path back and ` +
    `then prints one row per ingest table saying whether the service key can write it, ` +
    `which also tells you which of the two it was.`);
}

// A gate that fails closed would silently disable every workflow the first
// time the settings row is missing or the RPC is absent. Fail OPEN: an
// unreachable gate means run, and say so in the log.
if (decision === null || decision === undefined || decision.run === undefined) {
  console.log('schedule gate unavailable - running anyway');
  return $input.all();
}

if (decision.run === false) {
  // Recorded, so a skipped run is visible on the Workflows page as a skip
  // rather than looking like a workflow that silently stopped working.
  return [{ json: { __skipped: true, reason: decision.reason || 'not scheduled',
                    minutes_since: decision.minutes_since ?? null,
                    every_minutes: decision.every_minutes ?? null } }];
}
return $input.all();

// Returning [] stops the workflow here. Everything below this node
// is skipped, which is the entire point of the gate.
const items = $input.all();
if (items.length === 1 && items[0].json && items[0].json.__skipped) {
  console.log('skipped: ' + items[0].json.reason);
  return [];
}
return items;

// ONE PATCH PER CITY, and never an INSERT.
//
// This used to be one bulk POST to /cities?on_conflict=city_key. It failed two
// different ways on a real database and both were mine:
//
//   23502  null value in column "display_name" ... violates not-null
//          Postgres evaluates NOT NULL on the PROPOSED ROW of an
//          INSERT ... ON CONFLICT DO UPDATE *before* it detects the conflict.
//          So a partial payload into a table with a NOT NULL column it does
//          not carry fails even when the row already exists - and it does
//          exist, every time, because these cities were loaded from `cities`
//          two nodes ago.
//
//   PGRST102  All object keys must match
//          A bulk POST array must have identical keys in every object. A
//          supported city carries the grid id and an unsupported one does
//          not, so any run with both shapes was refused outright.
//
// PATCH fixes both and is the honest verb anyway: `cities` is the roster you
// maintain by hand, and this workflow only ever annotates a row that is
// already there. It must never be able to create a half-empty city.
//
// Every row is normalised to the same keys so the payload is uniform whichever
// path built it, and there is always at least one item so the branch cannot
// end up running zero times and looking like it succeeded.
const support = $('Guard: did anything parse?').first().json.support ?? [];

const KEYS = ['nws_supported', 'nws_station_id', 'nws_grid_wfo', 'nws_grid_x',
              'nws_grid_y', 'nws_checked_at'];

const items = support
  .filter((s) => s && s.city_key)
  .map((s) => {
    const patch = {};
    for (const k of KEYS) patch[k] = s[k] ?? null;
    return { json: { city_key: s.city_key, patch } };
  });

if (!items.length) {
  // A filter that matches no row: the request is made, changes nothing, and
  // returns cleanly - so the Summary node's write guard still has a node to
  // read and the branch is visibly "ran, nothing to do" rather than absent.
  return [{ json: { city_key: '__ad4_no_city__', patch: { nws_checked_at: null }, nothing_to_save: true } }];
}
return items;

// live_weather rows from this workflow are INSTRUMENT readings at the ICAO
// the market settles on. Say so on the row: P1.5 writes source='open-meteo',
// source_kind='model', and a merge upsert keeps whatever the other writer
// left, so without this stamp a station reading sat under a 'model' label
// and the desk's station-only gate (S5) could not trust the column it reads.
const p = $('Guard: did anything parse?').first().json;
const liveRows = (p.liveRows || []).map(r => ({ ...r, obs_source: 'NWS', source: 'NWS', source_kind: 'station' }));
return [{ json: { ...p, liveRows } }];
